SELECT 'With Attorney' as attorney_status, COUNT(*) as total_cases, SUM(CASE WHEN LOWER(statustag) = 'certified' THEN 1 ELSE 0 END) as approved_cases, ROUND(100.0 * SUM(CASE WHEN LOWER(statustag) = 'certified' THEN 1 ELSE 0 END) / COUNT(*), 2) as approval_rate FROM cases WHERE filekey IN (SELECT docketkey FROM case_attorney)
UNION ALL
SELECT 'Without Attorney', COUNT(*), SUM(CASE WHEN LOWER(statustag) = 'certified' THEN 1 ELSE 0 END), ROUND(100.0 * SUM(CASE WHEN LOWER(statustag) = 'certified' THEN 1 ELSE 0 END) / COUNT(*), 2) FROM cases WHERE filekey NOT IN (SELECT docketkey FROM case_attorney);

